      '{\n  "id": "angelus",\n  "title": "The Angelus (Regina Caeli in Eastertide)",\n  "description": "Three daily pauses recalling the Incarnation — 6am, noon, 6pm · ~3 min",\n  "family": "routine",\n  "schedules": [\n    {\n      "type": "timeOfDay",\n      "hour": 6,\n      "minute": 0,\n      "baseLabel": "angelus",\n      "variants": [\n        {\n          "months": [],\n          "seasons": ["Easter", "Eastertide", "Pentecost"],\n          "variantId": "regina_caeli"\n        }\n      ]\n    },\n    {\n      "type": "timeOfDay",\n      "hour": 12,\n      "minute": 0,\n      "baseLabel": "angelus",\n      "variants": [\n        {\n          "months": [],\n          "seasons": ["Easter", "Eastertide", "Pentecost"],\n          "variantId": "regina_caeli"\n        }\n      ]\n    },\n    {\n      "type": "timeOfDay",\n      "hour": 18,\n      "minute": 0,\n      "baseLabel": "angelus",\n      "variants": [\n        {\n          "months": [],\n          "seasons": ["Easter", "Eastertide", "Pentecost"],\n          "variantId": "regina_caeli"\n        }\n      ]\n    }\n  ],\n  "session": {\n    "id": "angelus-session",\n    "steps": [\n      {\n        "type": "verse",\n        "id": "angelus-v1",\n        "versicle": "The Angel of the Lord declared unto Mary.",\n        "response": "And she conceived of the Holy Spirit."\n      },\n      {\n        "type": "verse",\n        "id": "angelus-v2",\n        "versicle": "Behold the handmaid of the Lord.",\n        "response": "Be it done unto me according to Thy word."\n      },\n      {\n        "type": "verse",\n        "id": "angelus-v3",\n        "versicle": "And the Word was made flesh.",\n        "response": "And dwelt among us."\n      },\n      {\n        "type": "prayer",\n        "id": "angelus-collect",\n        "title": "The Angelus Collect",\n        "contentRef": "angelus_collect"\n      }\n    ]\n  },\n  "content": {\n    "angelus_collect": {\n      "id": "angelus_collect",\n      "text": "V. Pray for us, O holy Mother of God.\\nR. That we may be made worthy of the promises of Christ.\\n\\nLet us pray. Pour forth, we beseech Thee, O Lord, Thy grace into our hearts; that we, to whom the Incarnation of Christ, Thy Son, was made known by the message of an angel, may by His Passion and Cross be brought to the glory of His Resurrection. Through the same Christ our Lord. Amen.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    },\n    "regina_caeli_collect": {\n      "id": "regina_caeli_collect",\n      "text": "O God, who by the Resurrection of Thine only-begotten Son, and by the co-operation of the Holy Ghost, hast given unto the world the joy of everlasting life; grant, we beseech Thee, that through the intercession of the Blessed Virgin Mary, His Mother, we may attain unto the joys of everlasting life. Through the same Christ our Lord. Amen.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    },\n    "regina_caeli_versicles": {\n      "id": "regina_caeli_versicles",\n      "text": "V. Queen of Heaven, rejoice, alleluia.\\nR. For He whom thou didst merit to bear, alleluia.\\nV. Has risen as He said, alleluia.\\nR. Pray for us to God, alleluia.\\nV. Rejoice and be glad, O Virgin Mary, alleluia.\\nR. For the Lord hath truly risen, alleluia.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    }\n  }\n}\n',
  'divine_mercy_novena':
      '{\n  "id": "divine_mercy_novena",\n  "title": "The Divine Mercy Novena",\n  "description": "Nine days of Mercy leading to Divine Mercy Sunday · ~5 min/day",\n  "family": "novena",\n  "schedule": {\n    "type": "easterOffset",\n    "startOffset": -2,\n    "lengthDays": 9\n  },\n  "session": {\n    "id": "divine-mercy-novena-session",\n    "steps": [\n      {\n        "type": "intercession",\n        "id": "dmn-novena-intention",\n        "title": "Novena Intention of the Day",\n        "prompt": "Offer today\'s novena intention for: {{day}} of the Divine Mercy Novena"\n      },\n      {\n        "type": "verse",\n        "id": "dmn-sign-of-cross",\n        "title": "Sign of the Cross",\n        "versicle": "In the name of the Father, and of the Son, and of the Holy Spirit.",\n        "response": "Amen."\n      },\n      {\n        "type": "repetition",\n        "id": "dmn-blood-water",\n        "title": "O Blood and Water",\n        "contentRef": "dmn_blood_water",\n        "count": 3\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-our-father",\n        "title": "Our Father (on the crucifix)",\n        "contentRef": "dmn_our_father"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-hail-mary-1",\n        "title": "Hail Mary (first of three beads)",\n        "contentRef": "dmn_hail_mary"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-hail-mary-2",\n        "title": "Hail Mary (second of three beads)",\n        "contentRef": "dmn_hail_mary"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-hail-mary-3",\n        "title": "Hail Mary (third of three beads)",\n        "contentRef": "dmn_hail_mary"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-creed",\n        "title": "Apostles\' Creed",\n        "contentRef": "dmn_apostles_creed"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-1-eternal-father",\n        "title": "Eternal Father (first decade)",\n        "contentRef": "dmn_eternal_father"\n      },\n      {\n        "type": "repetition",\n        "id": "dmn-decade-1-for-the-sake",\n        "title": "For the Sake of His Sorrowful Passion (first decade)",\n        "contentRef": "dmn_for_the_sake",\n        "count": 10\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-1-glory-be",\n        "title": "Glory Be (first decade)",\n        "contentRef": "dmn_glory_be"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-2-eternal-father",\n        "title": "Eternal Father (second decade)",\n        "contentRef": "dmn_eternal_father"\n      },\n      {\n        "type": "repetition",\n        "id": "dmn-decade-2-for-the-sake",\n        "title": "For the Sake of His Sorrowful Passion (second decade)",\n        "contentRef": "dmn_for_the_sake",\n        "count": 10\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-2-glory-be",\n        "title": "Glory Be (second decade)",\n        "contentRef": "dmn_glory_be"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-3-eternal-father",\n        "title": "Eternal Father (third decade)",\n        "contentRef": "dmn_eternal_father"\n      },\n      {\n        "type": "repetition",\n        "id": "dmn-decade-3-for-the-sake",\n        "title": "For the Sake of His Sorrowful Passion (third decade)",\n        "contentRef": "dmn_for_the_sake",\n        "count": 10\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-3-glory-be",\n        "title": "Glory Be (third decade)",\n        "contentRef": "dmn_glory_be"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-4-eternal-father",\n        "title": "Eternal Father (fourth decade)",\n        "contentRef": "dmn_eternal_father"\n      },\n      {\n        "type": "repetition",\n        "id": "dmn-decade-4-for-the-sake",\n        "title": "For the Sake of His Sorrowful Passion (fourth decade)",\n        "contentRef": "dmn_for_the_sake",\n        "count": 10\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-4-glory-be",\n        "title": "Glory Be (fourth decade)",\n        "contentRef": "dmn_glory_be"\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-5-eternal-father",\n        "title": "Eternal Father (fifth decade)",\n        "contentRef": "dmn_eternal_father"\n      },\n      {\n        "type": "repetition",\n        "id": "dmn-decade-5-for-the-sake",\n        "title": "For the Sake of His Sorrowful Passion (fifth decade)",\n        "contentRef": "dmn_for_the_sake",\n        "count": 10\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-decade-5-glory-be",\n        "title": "Glory Be (fifth decade)",\n        "contentRef": "dmn_glory_be"\n      },\n      {\n        "type": "repetition",\n        "id": "dmn-holy-god",\n        "title": "Holy God, Holy Mighty One, Holy Immortal One",\n        "contentRef": "dmn_holy_god",\n        "count": 3\n      },\n      {\n        "type": "prayer",\n        "id": "dmn-closing",\n        "title": "Jesus, I trust in You!",\n        "contentRef": "dmn_jesus_trust"\n      }\n    ]\n  },\n  "content": {\n    "dmn_blood_water": {\n      "id": "dmn_blood_water",\n      "text": "O Blood and Water, which gushed forth from the Heart of Jesus as a fountain of mercy for us, I trust in You.",\n      "source": "Chaplet of the Divine Mercy tradition (reproduced e.g. by the USCCB)",\n      "license": "public-domain (universally reproduced; attribution: USCCB/MARIANS wording)"\n    },\n    "dmn_our_father": {\n      "id": "dmn_our_father",\n      "text": "Our Father, Who art in heaven, hallowed be Thy name; Thy kingdom come; Thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil. Amen.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    },\n    "dmn_hail_mary": {\n      "id": "dmn_hail_mary",\n      "text": "Hail Mary, full of grace, the Lord is with thee; blessed art thou amongst women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    },\n    "dmn_apostles_creed": {\n      "id": "dmn_apostles_creed",\n      "text": "I believe in God, the Father Almighty, Creator of heaven and earth; and in Jesus Christ, His only Son, our Lord; who was conceived by the Holy Spirit, born of the Virgin Mary, suffered under Pontius Pilate, was crucified, died, and was buried. He descended into hell; the third day He arose again from the dead. He ascended into heaven, sits at the right hand of God, the Father Almighty; from thence He shall come to judge the living and the dead. I believe in the Holy Spirit, the holy Catholic Church, the communion of Saints, the forgiveness of sins, the resurrection of the body, and life everlasting. Amen.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    },\n    "dmn_eternal_father": {\n      "id": "dmn_eternal_father",\n      "text": "Eternal Father, I offer You the Body and Blood, Soul and Divinity of Your Dearly Beloved Son, Our Lord Jesus Christ, in atonement for our sins and those of the whole world.",\n      "source": "Chaplet of the Divine Mercy tradition (reproduced e.g. by the USCCB)",\n      "license": "public-domain (universally reproduced; attribution: USCCB/MARIANS wording)"\n    },\n    "dmn_for_the_sake": {\n      "id": "dmn_for_the_sake",\n      "text": "For the sake of His sorrowful Passion, have mercy on us and on the whole world.",\n      "source": "Chaplet of the Divine Mercy tradition (reproduced e.g. by the USCCB)",\n      "license": "public-domain (universally reproduced; attribution: USCCB/MARIANS wording)"\n    },\n    "dmn_glory_be": {\n      "id": "dmn_glory_be",\n      "text": "Glory be to the Father, and to the Son, and to the Holy Spirit. As it was in the beginning, is now, and ever shall be, world without end. Amen.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    },\n    "dmn_holy_god": {\n      "id": "dmn_holy_god",\n      "text": "Holy God, Holy Mighty One, Holy Immortal One, have mercy on us and on the whole world.",\n      "source": "Chaplet of the Divine Mercy tradition (reproduced e.g. by the USCCB)",\n      "license": "public-domain (universally reproduced; attribution: USCCB/MARIANS wording)"\n    },\n    "dmn_jesus_trust": {\n      "id": "dmn_jesus_trust",\n      "text": "Jesus, I trust in You!",\n      "source": "Chaplet of the Divine Mercy tradition (reproduced e.g. by the USCCB)",\n      "license": "public-domain (universally reproduced; attribution: USCCB/MARIANS wording)"\n    }\n  },\n  "variants": [\n    {\n      "id": "day-1",\n      "title": "Day 1",\n      "dayIndex": 1,\n      "intention": "All mankind, especially sinners: that the whole world may come to know the mercy of God and trust in it.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-2",\n      "title": "Day 2",\n      "dayIndex": 2,\n      "intention": "Priests and religious: that, drawn from the abyss of His mercy, they may bring His pardon to every soul entrusted to them.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-3",\n      "title": "Day 3",\n      "dayIndex": 3,\n      "intention": "Devout and faithful souls: that the mercy of God may accompany them on every path of their life.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-4",\n      "title": "Day 4",\n      "dayIndex": 4,\n      "intention": "Those who do not believe in God and those who do not yet know Him: that the light of His mercy may shine upon their darkness.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-5",\n      "title": "Day 5",\n      "dayIndex": 5,\n      "intention": "Souls separated from the Church: that the charity of God may gather every straying soul back into one fold.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-6",\n      "title": "Day 6",\n      "dayIndex": 6,\n      "intention": "Meek and humble souls and the souls of little children: that their innocence may draw down the mercy of God upon the whole world.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-7",\n      "title": "Day 7",\n      "dayIndex": 7,\n      "intention": "Souls who venerate His mercy: that, dwelling in the merciful Heart of Jesus, they may draw from it all that they need.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-8",\n      "title": "Day 8",\n      "dayIndex": 8,\n      "intention": "Souls in purgatory: that the mercy of God may refresh them in their trial and open heaven to them in due time.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    },\n    {\n      "id": "day-9",\n      "title": "Day 9",\n      "dayIndex": 9,\n      "intention": "Lukewarm souls: that, kindled by the fire of His mercy, they may make an act of perfect trust in Jesus.",\n      "source": "Chaplet novena tradition (St. Faustina request summaries)",\n      "license": "public-domain summary"\n    }\n  ]\n}\n',
  'five_first_saturdays':
      '{\n  "id": "five_first_saturdays",\n  "title": "Five First Saturdays of Our Lady",\n  "description": "Five consecutive First Saturdays for the Immaculate Heart · monthly",\n  "family": "commitment",\n  "schedule": {\n    "type": "consecutiveCommitments",\n    "anchor": {\n      "type": "nthWeekdayOfMonth",\n      "weekday": 6,\n      "nth": 1\n    },\n    "count": 5,\n    "policy": "strict",\n    "windows": [\n      {\n        "item": "confession",\n        "beforeDays": 8,\n        "afterDays": 8\n      }\n    ]\n  },\n  "session": {\n    "id": "five-first-saturdays-session",\n    "steps": [\n      {\n        "type": "checkpoint",\n        "id": "ffs-confession",\n        "title": "Sacramental Confession",\n        "item": "confession",\n        "requiredForCompletion": false\n      },\n      {\n        "type": "checkpoint",\n        "id": "ffs-communion",\n        "title": "Holy Communion",\n        "item": "communion",\n        "requiredForCompletion": true\n      },\n      {\n        "type": "beadGroup",\n        "id": "ffs-decade-1",\n        "title": "The First Joyful Mystery",\n        "mysteryTitle": "The Annunciation",\n        "mysteryFruit": "Humility",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "beadGroup",\n        "id": "ffs-decade-2",\n        "title": "The Second Joyful Mystery",\n        "mysteryTitle": "The Visitation",\n        "mysteryFruit": "Charity",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "beadGroup",\n        "id": "ffs-decade-3",\n        "title": "The Third Joyful Mystery",\n        "mysteryTitle": "The Nativity",\n        "mysteryFruit": "Poverty of spirit",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "beadGroup",\n        "id": "ffs-decade-4",\n        "title": "The Fourth Joyful Mystery",\n        "mysteryTitle": "The Presentation",\n        "mysteryFruit": "Obedience",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "beadGroup",\n        "id": "ffs-decade-5",\n        "title": "The Fifth Joyful Mystery",\n        "mysteryTitle": "The Finding in the Temple",\n        "mysteryFruit": "Seeking God",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "reflection",\n        "id": "ffs-meditation",\n        "title": "Fifteen Minutes of Meditation",\n        "textRef": "ffs_meditation",\n        "durationSeconds": 900\n      }\n    ]\n  },\n  "content": {\n    "ffs_meditation": {\n      "id": "ffs_meditation",\n      "text": "Set apart these fifteen minutes for Our Lady, as she asked on the First Saturdays: a quarter-hour of meditation on the mysteries of the Holy Rosary, kept in reparation to her Immaculate Heart. Sit with her now, mystery by mystery. At the Annunciation, ask for her humility, for God found in her His dwelling because she made herself lowly. At the Visitation, learn her charity, for no sooner had she conceived than she crossed the hill country to serve. At the Nativity, adore the Child in poverty of spirit, laid in a manger because there was no room. At the Presentation, follow her obedience, for she kept every ordinance of the Law for Him who gave the Law. At the Finding in the Temple, seek God as she sought Him, sorrowing and believing until she found Him. Close by returning to her Heart, pierced and thorn-crowned by our sins, and offer her your company as the reparation she asked for: one First Saturday more in the series of five, for the glory of her Son.",\n      "source": "Fatima 1917 request",\n      "license": "public-domain (Our Lady\'s First Saturday request)"\n    }\n  }\n}\n',
  'mercy_hour':
      '{\n  "id": "mercy_hour",\n  "title": "The Hour of Mercy",\n  "description": "Recall Christ’s Passion at 3pm with Divine Mercy prayers · ~5 min",\n  "family": "routine",\n  "schedules": [\n    {\n      "type": "timeOfDay",\n      "hour": 15,\n      "minute": 0,\n      "baseLabel": "mercy_hour"\n    }\n  ],\n  "session": {\n    "id": "mercy-hour-session",\n    "steps": [\n      {\n        "type": "prayer",\n        "id": "mercy-hour-prayer",\n        "title": "The Hour of Mercy",\n        "contentRef": "mercy_hour_prayer"\n      },\n      {\n        "type": "repetition",\n        "id": "mercy-hour-repetition",\n        "title": "O Blood and Water",\n        "contentRef": "mercy_hour_repetition",\n        "count": 3\n      }\n    ]\n  },\n  "content": {\n    "mercy_hour_prayer": {\n      "id": "mercy_hour_prayer",\n      "text": "You expired, Jesus, but the source of life gushed forth for souls, and an ocean of mercy opened up for the whole world. O Blood and Water, which gushed forth from the Heart of Jesus as a fountain of mercy for us, I trust in You.",\n      "source": "The Diary of St. Faustina (short invocations)",\n      "license": "short-phrase (attributed, widely-reproduced)"\n    },\n    "mercy_hour_repetition": {\n      "id": "mercy_hour_repetition",\n      "text": "O Blood and Water, which gushed forth from the Heart of Jesus as a fountain of mercy for us, I trust in You.",\n      "source": "The Diary of St. Faustina (short invocations)",\n      "license": "short-phrase (attributed, widely-reproduced)"\n    }\n  }\n}\n',
  'nine_first_fridays':
      '{\n  "id": "nine_first_fridays",\n  "title": "Nine First Fridays of the Sacred Heart",\n  "description": "Nine consecutive First Fridays honoring the Sacred Heart · monthly",\n  "family": "commitment",\n  "schedule": {\n    "type": "consecutiveCommitments",\n    "anchor": {\n      "type": "nthWeekdayOfMonth",\n      "weekday": 5,\n      "nth": 1\n    },\n    "count": 9,\n    "policy": "strict"\n  },\n  "session": {\n    "id": "nine-first-fridays-session",\n    "steps": [\n      {\n        "type": "prayer",\n        "id": "nff-offering",\n        "title": "Act of Offering",\n        "contentRef": "nff_act_of_offering"\n      },\n      {\n        "type": "checkpoint",\n        "id": "nff-communion",\n        "title": "Holy Communion",\n        "item": "communion",\n        "requiredForCompletion": true\n      },\n      {\n        "type": "prayer",\n        "id": "nff-reparation",\n        "title": "Act of Reparation",\n        "contentRef": "nff_act_of_reparation"\n      }\n    ]\n  },\n  "content": {\n    "nff_act_of_offering": {\n      "id": "nff_act_of_offering",\n      "text": "Adorable Heart of Jesus, I come this First Friday to fulfill the devotion Thou Thyself didst ask of those who love Thee. In union with the Heart of Thy Blessed Mother, and with the offering which Thy Divine Heart made to Thy Eternal Father upon the altar of the Cross, I offer Thee my heart, my prayers, and all that I am this day: an act of love, of thanksgiving, and of reparation for the sins committed against Thee. Receive this offering, I beseech Thee, and let these nine First Fridays be for the glory of Thy Heart and for the salvation of my soul. Amen.",\n      "source": "Traditional Sacred Heart devotions (19th-century collections)",\n      "license": "public-domain"\n    },\n    "nff_act_of_reparation": {\n      "id": "nff_act_of_reparation",\n      "text": "O Sacred Heart of Jesus, loving and merciful beyond all measure, I adore Thee and I love Thee with my whole heart. Behold me prostrate before Thee in a spirit of reparation, offering Thee satisfaction for all the sins by which I have offended Thy love, and for all the indifference and irreverence with which Thy Heart is wounded wherever It is least loved. For the glory of Thy Heart, for the conversion of sinners, and for the grace of final repentance which Thou hast promised to those who honor Thee in nine First Fridays, I unite my poor prayers to the homages of Thy Blessed Mother and of all Thy faithful servants. Heart of Jesus, offended by our sins, have mercy on us. Sacred Heart of Jesus, I trust in Thee. Amen.",\n      "source": "Traditional Sacred Heart devotions (19th-century collections)",\n      "license": "public-domain"\n    }\n  }\n}\n',
  'novena_54_day':
      '{\n  "id": "novena_54_day",\n  "title": "The 54-Day Rosary Novena",\n  "description": "54-day Rosary novena — 27 days petition, 27 days thanksgiving · ~15 min/day",\n  "family": "novena",\n  "schedule": {\n    "type": "sessionSeries",\n    "startDate": "2026-11-10",\n    "lengthDays": 54\n  },\n  "session": {\n    "id": "novena-54-day-session",\n    "steps": [\n      {\n        "type": "verse",\n        "id": "novena-54-sign-of-cross",\n        "title": "Sign of the Cross",\n        "versicle": "In the name of the Father, and of the Son, and of the Holy Spirit.",\n        "response": "Amen."\n      },\n      {\n        "type": "prayer",\n        "id": "novena-54-petition-opening",\n        "title": "Petition phase opening (days 1-27)",\n        "contentRef": "petition-opening"\n      },\n      {\n        "type": "prayer",\n        "id": "novena-54-thanksgiving-opening",\n        "title": "Thanksgiving phase opening (days 28-54)",\n        "contentRef": "thanksgiving-opening"\n      },\n      {\n        "type": "beadGroup",\n        "id": "novena-54-decade-1",\n        "title": "First Decade",\n        "mysteryTitle": "{{mysteryTitle}}",\n        "mysteryFruit": "{{mysteryFruit}}",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "beadGroup",\n        "id": "novena-54-decade-2",\n        "title": "Second Decade",\n        "mysteryTitle": "{{mysteryTitle}}",\n        "mysteryFruit": "{{mysteryFruit}}",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "beadGroup",\n        "id": "novena-54-decade-3",\n        "title": "Third Decade",\n        "mysteryTitle": "{{mysteryTitle}}",\n        "mysteryFruit": "{{mysteryFruit}}",\n        "hailMaryCount": 10,\n        "includeFatimaPrayer": true\n      },\n      {\n        "type": "verse",\n        "id": "novena-54-final-verse",\n        "title": "Final versicle and response",\n        "versicle": "V. Pray for us, O holy Mother of God.",\n        "response": "R. That we may be made worthy of the promises of Christ."\n      },\n      {\n        "type": "prayer",\n        "id": "novena-54-petition-closing",\n        "title": "Petition phase closing (days 1-27)",\n        "contentRef": "petition-closing"\n      },\n      {\n        "type": "prayer",\n        "id": "novena-54-thanksgiving-closing",\n        "title": "Thanksgiving phase closing (days 28-54)",\n        "contentRef": "thanksgiving-closing"\n      },\n      {\n        "type": "prayer",\n        "id": "novena-54-collect",\n        "title": "Closing collect",\n        "contentRef": "novena-closing"\n      }\n    ]\n  },\n  "content": {\n    "petition-opening": {\n      "id": "petition-opening",\n      "text": "Hail, Queen of the Most Holy Rosary, my Mother Mary, hail! At thy feet I humbly kneel to offer thee a Crown of Roses, each rose recalling to thee a holy mystery, each 10 bound together with my petition for a particular grace.\\n\\nO Holy Queen, dispenser of God\'s graces, and Mother of all who invoke thee! Thou canst not look upon my gift and fail to see its binding. As thou receivest my gift, so wilt thou receive my petition; from thy bounty thou wilt give me the favor I so earnestly and trustingly seek. I despair of nothing that I ask of thee. Show thyself my Mother!",\n      "source": "Traditional 54-day Rosary Novena (Pompeii, 1884 tradition; widely circulated public-domain-era text; rose-color clause of the offering stanza omitted)",\n      "license": "public-domain"\n    },\n    "thanksgiving-opening": {\n      "id": "thanksgiving-opening",\n      "text": "Hail, Queen of the Most Holy Rosary, my Mother Mary, hail! At thy feet I gratefully kneel to offer thee a Crown of Roses, each rose recalling to thee a holy mystery, each 10 bound together with my petition for a particular grace.\\n\\nO Holy Queen, dispenser of God\'s graces, and Mother of all who invoke thee! Thou canst not look upon my gift and fail to see its binding. As thou receivest my gift, so wilt thou receive my thanksgiving; from thy bounty thou hast given me the favor I so earnestly and trustingly sought. I despaired not of what I asked of thee, and thou hast truly shown thyself my Mother.",\n      "source": "Traditional 54-day Rosary Novena (Pompeii, 1884 tradition; widely circulated public-domain-era text; rose-color clause of the offering stanza omitted)",\n      "license": "public-domain"\n    },\n    "petition-closing": {\n      "id": "petition-closing",\n      "text": "Sweet Mother Mary, I offer thee this spiritual communion to bind my bouquets in a wreath to place upon thy brow. O my Mother! Look with favor upon my gift, and in thy love obtain for me (specify request). Amen.",\n      "source": "Traditional 54-day Rosary Novena (Pompeii, 1884 tradition; widely circulated public-domain-era text; rose-color clause of the offering stanza omitted)",\n      "license": "public-domain"\n    },\n    "thanksgiving-closing": {\n      "id": "thanksgiving-closing",\n      "text": "Sweet Mother Mary, I offer thee this Spiritual Communion to bind my bouquets in a wreath to place upon thy brow in thanksgiving for (specify request) which thou in thy love hast obtained for me. Amen.",\n      "source": "Traditional 54-day Rosary Novena (Pompeii, 1884 tradition; widely circulated public-domain-era text; rose-color clause of the offering stanza omitted)",\n      "license": "public-domain"\n    },\n    "novena-closing": {\n      "id": "novena-closing",\n      "text": "Let us pray. O God, whose only-begotten Son, by His life, death, and resurrection, has purchased for us the rewards of eternal life; grant, we beseech Thee, that while meditating upon these mysteries of the most Holy Rosary of the Blessed Virgin Mary, we may imitate what they contain and obtain what they promise, through the same Christ our Lord. Amen.",\n      "source": "Traditional Roman devotion",\n      "license": "public-domain"\n    }\n  },\n  "reminders": {\n    "startAnchor": {\n      "pickedBy": "user",\n      "note": "startDate is a user-picked enrollment parameter (day 1 of the novena); the app recomputes it at enrollment, and the fixture\'s 2026-11-10 is a placeholder value"\n    }\n  },\n  "variants": [\n    {\n      "id": "day-1",\n      "dayIndex": 1,\n      "phase": "petition",\n      "mysterySet": "joyful",\n      "petition": "I bind these snow-white buds with a petition for the virtue of humility and humbly lay this bouquet at thy feet.",\n      "virtue": "humility"\n    },\n    {\n      "id": "day-2",\n      "dayIndex": 2,\n      "phase": "petition",\n      "mysterySet": "sorrowful",\n      "petition": "I bind these blood red roses with a petition for the virtue of resignation to the will of God and humbly lay this bouquet at thy feet.",\n      "virtue": "resignation to the will of God"\n    },\n    {\n      "id": "day-3",\n      "dayIndex": 3,\n      "phase": "petition",\n      "mysterySet": "glorious",\n      "petition": "I bind these full-blown roses with a petition for the virtue of faith and humbly lay this bouquet at thy feet.",\n      "virtue": "faith"\n    },\n    {\n      "id": "day-4",\n      "dayIndex": 4,\n      "phase": "petition",\n      "mysterySet": "joyful",\n      "petition": "I bind these snow-white buds with a petition for the virtue of humility and humbly lay this bouquet at thy feet.",\n      "virtue": "humility"\n    },\n    {\n      "id": "day-5",\n      "dayIndex": 5,\n      "phase": "petition",\n      "mysterySet": "sorrowful",\n      "petition": "I bind these blood red roses with a petition for the virtue of resignation to the will of God and humbly lay this bouquet at thy feet.",\n      "virtue": "resignation to the will of God"\n    },\n    {\n      "id": "day-6",\n      "dayIndex": 6,\n      "phase": "petition",\n      "mysterySet": "glorious",\n      "petition": "I bind these full-blown roses with a petition for the virtue of faith and humbly lay this bouquet at thy 